        markY={SPARK_MARK.cn_us_spread_10y}
        onOpen={open("cn_us_spread_10y", "中美 10 年利差", spread)}
      />
      <MetricCard
        label="VIX 恐慌指数"
        value={data.vix == null ? "暂不可用" : data.vix.value.toFixed(2)}
        sub={
          data.vix == null
            ? "yfinance 限流，稍后刷新重试"
