        subtitle: `已记录 多 ${fmt(cur?.bullish, 0)}% / 空 ${fmt(cur?.bearish, 0)}%（共 ${obs.length} 期，周频）`,
        dates,
        series: [
          { name: "看多 %", values: obs.map((o) => o.bullish ?? null), color: "#e33d47" },
          { name: "看空 %", values: obs.map((o) => o.bearish ?? null), color: "#0b9b64" },
