          <span className="pg-kv">
            <span className="k">数据源</span>
            <b>{ov ? (allErrors.length > 0 ? "概览数据源：部分不可用" : "概览数据源：本次未报告错误") : "未知"}</b>
          </span>
        </div>}
        {activeSection !== "fund-sec-market" && <div className="pg-head-actions">
