import { useEffect, useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { ERP_REFERENCE_QUERY_KEY, ERP_REFERENCE_URL, parseErpReference } from "../observation-library/erpReferenceData";
import { ERP_BAND_METHOD } from "../observation-library/erpBands";
import { breadthInput, chartLink, erpInput, parseBreadth, type BreadthMarket } from "./adapters";
import { buildAlertSnapshot, eventLabel, parseSeen, type AlertSnapshot } from "./model";
import { acknowledge, SEEN_EVENT, SEEN_KEY } from "./storage";
import "./style.css";

async function getJson(url: string, signal: AbortSignal): Promise<unknown> {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`资料读取失败 (${response.status})`);
  return response.json();
}

function useBreadth(market: BreadthMarket) {
  return useQuery({ queryKey: ["homeObservationBreadth", market, 90],
    queryFn: async ({ signal }) => parseBreadth(await getJson(
      `/api/market-context/breadth-history?market_id=${market}&lookback_days=90&include_observation=true`, signal), market),
    staleTime: 5 * 60_000, refetchInterval: 5 * 60_000, retry: false });
}

function readSeen() {
  try { return { seen: parseSeen(localStorage.getItem(SEEN_KEY)), failed: false }; }
  catch { return { seen: {}, failed: true }; }
}

const today = () => new Intl.DateTimeFormat("sv-SE", { timeZone: "Asia/Shanghai" }).format(new Date());
const format = (n: number | null | undefined) => n == null || !Number.isFinite(n) ? "—" : n.toFixed(2);

function meaning(s: AlertSnapshot): string {
  if (s.kind === "erp") return "上轨：相对便宜、反弹观察；下轨：相对偏贵，未证实能报顶。";
  return "离开低位看修复，离开高位看回落；高低位本身不是买卖点。";
}

function AlertRow({ snapshot: s, href, pending, onRead }: {
  snapshot: AlertSnapshot; href: string; pending: boolean; onRead: () => void;
}) {
  const fresh = s.quality === "ready";
  const lastNew = s.newEvents[s.newEvents.length - 1];
  const quality = pending && !s.latest ? "读取中" : s.quality === "historical" ? "历史快照 · 未自动更新"
    : s.quality === "stale" ? "待更新" : s.quality === "error" ? "读取失败" : s.quality === "missing" ? "资料不足" : "资料可用";
  return <article className={`moa-item moa-${s.quality}`} aria-label={s.label}>
    <div className="moa-item-head"><h3>{s.label}</h3><span className="moa-quality" title={s.qualityLabel}>{quality}</span></div>
    <div className="moa-reading"><strong>{format(s.latest?.value)}<small>{s.kind === "erp" ? "百分点" : "%"}</small></strong>
      <span>{fresh ? "" : "末次："}{s.positionLabel}</span></div>
    <div className="moa-bounds"><span>{s.kind === "erp" ? "下轨" : "低位线 P10"} <b>{format(s.latest?.lower)}</b></span>
      <span>{s.kind === "erp" ? "上轨" : "高位线 P90"} <b>{format(s.latest?.upper)}</b></span></div>
    <p className="moa-meaning">{meaning(s)}</p>
    {lastNew ? <div className="moa-new"><span>新变化 · {eventLabel(s.kind, lastNew.event)} <time>{lastNew.date}</time>
      {s.newEvents.length > 1 ? ` 等${s.newEvents.length}次` : ""}</span><button onClick={onRead}>知道了</button></div>
      : s.revised && fresh ? <p className="moa-event">同日数据已修订，未记为新穿越</p>
      : fresh && s.latest ? <p className="moa-event">{eventLabel(s.kind, s.latest.event)}</p>
      : <p className="moa-event">{s.quality === "historical" ? "仅供历史回看，当前提醒未启用"
        : s.quality === "error" ? "本次读取失败，暂不判断新变化"
        : s.quality === "stale" ? "旧读数仅供回看，当前变化未知" : "等待完整读数与轨道"}</p>}
    <footer><time>数据 {s.latest?.date ?? "—"}{s.kind === "erp" ? " · 周频" : ""}</time>
      <Link to={href} onClick={onRead}>看走势图 <span aria-hidden="true">↗</span></Link></footer>
    {s.lastEvent && <details className="moa-history"><summary>最近一次历史变化 · {s.lastEvent.date}</summary>
      <p>{eventLabel(s.kind, s.lastEvent.event)} · 读数 {format(s.lastEvent.value)}；当时下界 {format(s.lastEvent.lower)}、上界 {format(s.lastEvent.upper)}。
        {s.kind === "breadth" ? "仅检索返回的近90条记录。" : "历史事件，不代表今天触发。"}</p>
    </details>}
  </article>;
}

export default function MarketObservationAlerts() {
  const [stored, setStored] = useState(readSeen);
  const [nowDate, setNowDate] = useState(today);
  const cn = useBreadth("CN_ALL_A");
  const us = useBreadth("SP500");
  const erp = useQuery({ queryKey: ERP_REFERENCE_QUERY_KEY,
    queryFn: async ({ signal }) => parseErpReference(await getJson(ERP_REFERENCE_URL, signal)),
    staleTime: 5 * 60_000, retry: false });
  const inputs = useMemo(() => [erpInput(erp.data, erp.isError), breadthInput("CN_ALL_A", cn.data, cn.isError),
    breadthInput("SP500", us.data, us.isError)], [erp.data, erp.isError, cn.data, cn.isError, us.data, us.isError]);
  const snapshots = inputs.map(input => buildAlertSnapshot(input, nowDate, stored.seen[input.id]));
  const newCount = snapshots.reduce((n, s) => n + s.newEvents.length, 0);
  const monitored = snapshots.filter((_, i) => !inputs[i].historicalOnly);
  const readyCount = monitored.filter(s => s.quality === "ready").length;
  const fetching = erp.isFetching || cn.isFetching || us.isFetching;
  const sources = [erp, cn, us];
  const hrefs = [chartLink("erp"), chartLink("CN_ALL_A"), chartLink("SP500")];

  useEffect(() => {
    const sync = (event?: StorageEvent) => {
      if (event && event.key !== SEEN_KEY && event.key !== null) return;
      setStored(readSeen());
    };
    const localSync = () => sync();
    window.addEventListener("storage", sync);
    window.addEventListener(SEEN_EVENT, localSync);
    const timer = window.setInterval(() => setNowDate(today()), 60_000);
    return () => { window.removeEventListener("storage", sync); window.removeEventListener(SEEN_EVENT, localSync); window.clearInterval(timer); };
  }, []);

  const markRead = (items: AlertSnapshot[]) => {
    if (!items.some(s => s.quality === "ready")) return;
    try {
      localStorage.setItem(SEEN_KEY, acknowledge(localStorage.getItem(SEEN_KEY), items));
      setStored(readSeen());
      window.dispatchEvent(new Event(SEEN_EVENT));
    } catch { setStored(previous => ({ ...previous, failed: true })); }
  };
  return <section className="market-observation-alerts" aria-labelledby="moa-title">
    <header className="moa-header"><div><h2 id="moa-title">市场提醒</h2>
      <span aria-live="polite">{newCount ? `${newCount}条新变化` : readyCount === 0 ? "当前提醒待资料更新"
        : readyCount < monitored.length ? `${readyCount}/${monitored.length}项宽度资料可用 · 其余待更新` : "宽度暂无新穿越 · 股债仅历史观察"}</span></div>
      <div className="moa-actions">{newCount > 0 && <button onClick={() => markRead(snapshots)}>全部已读</button>}
        <button disabled={fetching} onClick={() => { void Promise.all([erp.refetch(), cn.refetch(), us.refetch()]); }}>{fetching ? "读取中…" : "刷新读数"}</button></div>
    </header>
    {stored.failed && <p className="moa-storage-error" role="status">浏览器未能保存已读状态，刷新后可能再次显示提醒。</p>}
    <div className="moa-grid">{snapshots.map((s, i) => <AlertRow key={s.id} snapshot={s} href={hrefs[i]}
      pending={sources[i].isPending} onRead={() => markRead([s])} />)}</div>
    <details className="moa-rules"><summary>提醒口径与依据</summary><div>
      <p>穿出上下界、重新回到界内时提示；持续在界外不重复报新变化。这里常驻显示读数，已读仅清除新变化标记。</p>
      <p>股债轨道：<a href={ERP_BAND_METHOD.url} target="_blank" rel="noreferrer">国信证券三年均值±2σ方法</a>的独立参照版，现有周频资料仅供历史回看。
        <Link to="/library?report=docs%2Fexperiments%2Fequity-bond-bands-effect-2026-11-01.md">查看效果检验</Link>：上轨有反弹线索，下轨未证明能预测顶部。</p>
      <p>宽度：站上50日均线的股票占比；低位/高位线为各自市场近1260条有效记录的P10/P90，最少252条、包含当日。属于历史统计边界，不是已验证的机会值或风险值。20/200日可进宽度图切换。</p>
      <p>首页打开时每5分钟重读系统资料；不会在页面关闭后推送。超过7个自然日未更新、读取失败或资料缺失时暂停新提醒；7天是资料时效容忍，与金融阈值无关。</p>
    </div></details>
  </section>;
}

